                        posY: worldAtSub.posY,
                        posZ: worldAtSub.posZ,
                        scaleW: worldAtSub.scaleW,
                        scaleH: worldAtSub.scaleH,
                        rotX: worldAtSub.rotX,
                        rotY: worldAtSub.rotY,
                        rotZ: worldAtSub.rotZ,
                        rotation: worldAtSub.rotZ
